const paths={key:'<circle cx="8" cy="8" r="5"/><path d="m12 12 9 9m-5-5 3-3m-6 0 3-3"/>',people:'<circle cx="8" cy="8" r="3"/><path d="M2 20v-3a6 6 0 0 1 12 0v3m2-15a3 3 0 0 1 0 6m2 3a5 5 0 0 1 4 5"/>',back:'<path d="m15 5-7 7 7 7"/>',arrow:'<path d="m9 5 7 7-7 7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',device:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',upload:'<path d="M4 15v5h16v-5M12 16V3m-5 5 5-5 5 5"/>',download:'<path d="M4 15v5h16v-5M12 3v13m-5-5 5 5 5-5"/>',spaces:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const ico=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.key}</svg>`;
const btn=(t,to,c='primary-button',disabled=false)=>`<button type="button" class="${c}" ${disabled?'disabled':''} data-to="${to}">${t}</button>`;
const field=(value='Quiet Room · 09月22日 · 01')=>`<div class="gateway-form"><label>通行密钥名称<input maxlength="40" aria-label="通行密钥名称" value="${value}"></label><p class="hint">在系统选择器中用这个名称辨认密钥。<br>以后创建的多个空间可共用这一把。</p></div>`;
const gateway=(title,desc,body,actions,icon='key')=>`<section class="gateway"><div class="gateway-mark">${ico(icon)}</div><div class="gateway-heading"><h1>${title}</h1><p>${desc}</p></div>${body}<div class="welcome-actions">${actions}</div></section>`;
const header=t=>`<header class="subhead"><button class="back" aria-label="返回" data-to="7">${ico('back')}</button><h1>${t}</h1></header>`;
const managed=(variant='normal')=>{const legacy=variant==='legacy',saved=variant==='saved',unsupported=variant==='unsupported';return `${header('通行密钥管理')}<div class="subbody"><div class="key-mark">${ico('key')}</div><p class="field-label">${legacy?'当前通行密钥':'通行密钥名称'}</p><h2 class="key-title">${legacy?'尚未设置名称':saved?'Quiet Room · 我的空间':'Quiet Room · 日常空间'}</h2><span class="pill">当前使用</span>${legacy?'<p class="hint">这把旧密钥没有应用内名称记录。<br>设置名称后，选密钥时更容易辨认。</p>':''}<div class="definition"><strong>多个空间，共用一把通行密钥</strong><p>创建新空间时优先复用。<br>修改名称不影响空间、聊天记录和解锁。</p></div>${saved?'<div class="pk-notice"><strong>名称已保存</strong>已通知系统更新显示名称。</div>':''}${unsupported?'<div class="pk-notice"><strong>当前环境暂不支持改名</strong>请在支持名称更新的浏览器和密码管理器中操作。</div>':''}<div class="bottom">${btn(legacy?'设置名称':'修改名称',10,'primary-button',unsupported)}<p class="hint">${unsupported?'暂不开放编辑，避免只改应用内备注。':'保存修改时，需要再次验证当前通行密钥。'}</p><p class="hint">此处显示应用保存的名称。</p></div></div>`};
const edit=(variant='normal')=>`${header('修改通行密钥名称')}<div class="subbody"><div class="edit-form"><label for="key-name">通行密钥名称</label><input id="key-name" maxlength="40" value="Quiet Room · 我的空间" ${variant==='saving'?'disabled':''}><div class="counter">17 / 40</div></div><p class="hint">下次选择通行密钥时，请认准此名称。<br>使用同一把密钥的空间无需重新绑定。</p>${variant==='failed'?'<p class="error" role="alert">名称更新未完成，仍保留原名称。<br>请重试，或取消本次修改。</p>':''}<div class="bottom">${btn(variant==='saving'?'请完成系统验证…':variant==='failed'?'重新验证并保存':'验证并保存',variant==='saving'?12:11,'primary-button',variant==='saving')}${btn('取消',9,'text-button')}<p class="hint">${variant==='saving'?'验证完成后提交修改。取消验证不会改名。':'使用当前通行密钥验证后保存。'}</p></div></div>`;
const setting=(label,icon,to,small='')=>`<button class="space-setting" data-to="${to}"><span class="space-setting-icon">${ico(icon)}</span><span class="space-setting-label">${label}${small?`<small>${small}</small>`:''}</span>${ico('arrow')}</button>`;
const screens={
1:{title:'欢迎页',note:'已有空间入口优先；创建与恢复仍保留',body:()=>gateway('有些话，<br>只留给彼此。','一个只属于两个人的私密空间。','<div class="copy"><p>无需手机号或邮箱。</p><p>已有空间？使用原来的通行密钥，<br>在这个浏览器继续。</p></div>',btn('使用已有通行密钥',5)+btn('创建私密空间',2,'secondary-button')+btn('恢复私密空间',4,'text-button')+'<small>选择系统中原来使用的那把密钥。</small>','people')},
2:{title:'首次创建 · 密钥命名',note:'在创建系统密钥前填写；不增加独立命名页',body:()=>gateway('设置通行密钥','给这把密钥一个容易辨认的名称。',field(),btn('创建通行密钥并继续',18)+btn('返回',1,'text-button'))},
3:{title:'首次加入 · 密钥命名',note:'邀请加入首次绑定复用同一命名组件',body:()=>gateway('加入私密空间','先设置通行密钥，保护此浏览器里的空间。',field(),btn('创建通行密钥并加入',18)+btn('返回',1,'text-button'),'people')},
4:{title:'重新绑定 · 密钥命名',note:'恢复后的既有绑定流程；原确认步骤保留',body:()=>gateway('重新绑定通行密钥','为恢复后的空间设置新的通行密钥。',field('Quiet Room · 恢复后的空间')+'<label class="confirm-line"><input type="checkbox" checked>我已了解：重新绑定将清除本地浏览器数据。</label>',btn('创建通行密钥并绑定',18)+btn('返回',1,'text-button'))},
5:{title:'新浏览器 · 等待旧端批准',note:'验证后进入；提供“重新选择通行密钥”',body:()=>gateway('等待原浏览器批准','打开原来使用的浏览器，解锁空间后核对六位码。','<div class="code">482 196</div><div class="expires">剩余 09:42</div><p class="line-note">原浏览器没有收到请求？<br>请确认已联网并解锁，或重新选择原来的通行密钥。</p>',btn('重新选择通行密钥',1,'secondary-button')+btn('取消接入',1,'text-button')+'<small>批准后先显示空间列表，聊天仍需对方授权。</small>','device')},
6:{title:'新浏览器 · 请求到期',note:'结束旧请求；不把到期解释成没有空间',body:()=>gateway('本次请求已过期','原有空间仍然保留，请重新发起接入。','<p class="line-note">请先打开原浏览器并解锁空间。<br>重新验证时，选择原来使用的通行密钥。</p>',btn('重新验证并接入',5)+btn('返回',1,'text-button'),'clock')},
7:{title:'设置 · 新增管理入口',note:'位于“本机”组；验证前不展示密钥名称',body:()=>`<div class="background-chat"><div class="chat-top"><span>日常</span>${ico('heart')}</div></div><div class="space-drawer-overlay is-visible"><section class="space-drawer"><header class="space-drawer-header"><button class="icon-button" aria-label="返回" data-to="18">${ico('back')}</button><h2>设置</h2><button class="icon-button" aria-label="关闭" data-to="18">${ico('close')}</button></header><div class="space-drawer-scroll"><section class="space-setting-group"><h3>当前空间</h3>${setting('已连接设备','device',18)}${setting('我的恢复码','key',4)}${setting('备份数据','upload',18)}${setting('恢复数据','download',4)}${setting('恢复其他空间','spaces',4)}</section><section class="space-setting-group"><h3>本机</h3>${setting('通行密钥管理','key',8,'验证后查看与修改名称')}${setting('在线状态样式','heart',7,'在线胶囊')}${setting('关闭自动遮蔽','shield',7)}</section><section class="space-setting-group"><h3>关于</h3>${setting('更新记录','clock',7)}</section></div></section></div>`},
8:{title:'进入管理 · 验证当前密钥',note:'点击设置入口直接唤起系统验证；图示应用底页',body:()=>gateway('验证通行密钥','验证后，查看当前通行密钥的名称并进行管理。','',btn('验证当前通行密钥',9)+btn('返回设置',7,'text-button'),'shield')},
9:{title:'管理页 · 已有名称',note:'已完成进入验证；只管理当前绑定密钥',body:()=>managed()},
10:{title:'修改名称',note:'编辑 → 验证并保存；不会新建或替换凭据',body:()=>edit()},
11:{title:'保存 · 再次验证',note:'系统验证由真实 Safari 提供；此图不伪造系统弹窗',body:()=>edit('saving')},
12:{title:'保存后的管理页',note:'显示新名称；不承诺可自动回读所有系统名称',body:()=>managed('saved')},
13:{title:'旧密钥 · 尚无名称记录',note:'不显示猜测的旧名称；设置名称沿用原凭据',body:()=>managed('legacy')},
14:{title:'进入验证取消或失败',note:'不显示敏感名称；允许重新验证或返回',body:()=>gateway('验证通行密钥','验证后，查看当前通行密钥的名称并进行管理。','<p class="error" role="alert">尚未完成验证，未打开通行密钥管理。</p>',btn('重新验证',9)+btn('返回设置',7,'text-button'),'shield')},
15:{title:'不支持改名 · 提前拦截',note:'仅查看已保存名称；不开放“只改本地备注”',body:()=>managed('unsupported')},
16:{title:'保存失败 · 保留原名',note:'适用于更新明确失败；草稿保留，可重试',body:()=>edit('failed')},
17:{title:'旧端 · 批准浏览器接入',note:'保留原两层授权；文案说明此步仅交付空间列表',body:()=>`<div class="background-chat"><div class="chat-top"><span>日常</span>${ico('heart')}</div></div><div class="space-drawer-overlay is-visible"><section class="approval"><h1>允许新浏览器接入？</h1><p>请与新浏览器上的六位码核对。<br>只批准你自己刚刚发起的请求。</p><div class="code">482 196</div><p>本次仅允许查看空间列表。<br>进入空间聊天，仍需对方授权。</p>${btn('核对一致，批准',18)}${btn('拒绝',7,'text-button')}</section></div>`},
18:{title:'空间列表接入后 · 权限边界',note:'沿用现有外壳；无消息、历史预览和输入框',body:()=>`<header class="subhead"><button class="back" data-to="7" aria-label="打开空间列表">${ico('spaces')}</button><h1>日常</h1><button class="close" data-to="1" aria-label="锁定">${ico('shield')}</button></header><div class="restricted"><div class="key-mark">${ico('people')}</div><h2>此空间尚未授权</h2><p>获得对方授权后，<br>即可在此浏览器聊天。</p><p>加入前的历史记录不会同步。</p></div><div class="restricted-bottom">${btn('申请对方授权',18)}</div>`}
};
screens[19]={title:'旧保险库 · 首次绑定',note:'既有旧保险库迁移完成验证后，复用命名组件',body:()=>gateway('绑定这台设备','为已有空间设置通行密钥，以后用它解锁。',field(),btn('创建通行密钥并绑定',9)+btn('返回',7,'text-button'))};
screens[20]={title:'保存结果待确认',note:'系统更新已提交，但本地记录保存失败；不声称回滚',body:()=>`${header('修改通行密钥名称')}<div class="subbody"><div class="key-mark">${ico('clock')}</div><h2 class="key-title">请确认名称更新结果</h2><p class="hint">已向系统提交新名称，但此浏览器未能保存名称记录。</p><div class="definition"><strong>本次提交的名称</strong><p>Quiet Room · 我的空间</p></div><p class="hint">可在系统密码管理器中核对。<br>通行密钥仍可用于解锁空间。</p><div class="bottom">${btn('重新验证并完成保存',11)}${btn('返回管理',9,'text-button')}</div></div>`};
screens[21]={title:'名称输入校验',note:'名称必填，1–40 个字符；不发起系统验证',body:()=>`${header('修改通行密钥名称')}<div class="subbody"><div class="edit-form"><label for="key-name">通行密钥名称</label><input id="key-name" maxlength="40" value="" aria-invalid="true" placeholder="例如 Quiet Room · 日常空间"><div class="counter">0 / 40</div></div><p class="error">请输入 1–40 个字符的名称。</p><div class="bottom">${btn('验证并保存',10,'primary-button',true)}${btn('取消',9,'text-button')}</div></div>`};
const groups={1:{title:'首次使用与浏览器接入',desc:'统一新密钥的可读名称；已有空间优先使用原密钥。保留旧端批准和空间对方授权。',ids:[1,2,3,4,5,6]},2:{title:'通行密钥管理',desc:'设置入口 → 验证当前密钥 → 查看名称 → 编辑 → 再次验证 → 保存。两次验证分别生效。',ids:[7,8,9,10,11,12]},3:{title:'旧密钥、异常与授权边界',desc:'旧密钥在原凭据上补齐名称。验证失败不开放管理；不支持改名时提前拦截，保存失败不改原名。',ids:[13,14,15,16,17,18]},4:{title:'深色模式 · 关键页面',desc:'沿用 Quiet Room 的深色 token，信息层级与浅色版本保持一致。',ids:[1,2,7,9,10,12]}};
groups[5]={title:'共用组件与保存边界',desc:'补齐旧保险库首次绑定、名称输入校验，以及系统更新与本地记录未同时完成时的处理。',ids:[19,20,21]};
const q=new URLSearchParams(location.search);const group=Number(q.get('board')||2);const solo=Number(q.get('screen')||0);let current=solo;
const phone=id=>`<figure class="tile"><figcaption class="tile-head"><h2><span>${String(id).padStart(2,'0')}</span>${screens[id].title}</h2><p>${screens[id].note}</p></figcaption><div class="phone"><div class="status"><span>9:41</span><span class="indicators"><svg viewBox="0 0 24 24"><path d="M3 17h2m3-4h2m3-4h2m3-4h2" stroke-width="3"/></svg><svg viewBox="0 0 24 24"><rect x="2" y="6" width="18" height="12" rx="3"/><path d="M23 10v4M6 9h10v6H6z" fill="currentColor"/></svg></span></div><div class="screen">${screens[id].body()}</div><div class="home"></div></div></figure>`;
function render(){if(solo){document.body.classList.add('solo');review.innerHTML=phone(current);return}const g=groups[group]||groups[2];review.innerHTML=`<header class="review-head"><div><div class="eyeline">QUIET ROOM / DESIGN REVIEW D1</div><h1>${g.title}</h1><p>${g.desc}</p></div><span class="badge">2026.09.22 · 待确认静态稿</span></header><div class="board">${g.ids.map(phone).join('')}</div><footer class="review-foot"><span>静态设计示意 · 所有名称、空间和六位码均为模拟数据 · 不包含真实系统弹窗</span><span>D1 · ${group} / 5</span></footer>${q.has('capture')?'':`<nav class="review-nav">${[1,2,3,4,5].map(n=>`<a href="?board=${n}">第 ${n} 组</a>`).join('')}<a href="?screen=7">单页演示（点击流转，不进行真实验证）</a></nav>`}`;}
render();document.addEventListener('click',e=>{const b=e.target.closest('[data-to]');if(!b||b.disabled)return;const id=Number(b.dataset.to);if(!screens[id])return;if(solo){current=id;render()}else location.href=`?screen=${id}`;});
window.designScreens=screens;
